//! Dataset Loading and Parsing
//!
//! Provides the `DatasetLoader` utility to read the CSV files generated by `dataset.rs`
//! and construct `Batch` Candle Tensors for training the GNN RAIM model.

use std::fs::File;
use std::io::{BufRead, BufReader};
use candle_core::{Device, Tensor, Result as CandleResult};

/// The maximum number of satellites per batch (padded or truncated to this size)
pub const MAX_SATS: usize = 32;

/// The dimensionality of the feature vector (SNR, EL, AZ, DOPPLER, LOCKTIME)
pub const NUM_FEATURES: usize = 5;

/// Represents a single training batch mapped to a specific GNSS epoch.
#[derive(Clone)]
pub struct Batch {
    /// Features: (Batch, MAX_SATS, NUM_FEATURES)
    pub features: Tensor,
    /// Target squared residuals: (Batch, MAX_SATS)
    pub residuals: Tensor,
    /// Mask identifying valid satellites vs padded zeros: (Batch, MAX_SATS)
    pub mask: Tensor,
}

/// Loads and batches GNSS epochs for GNN training.
pub struct DatasetLoader {
    /// Ordered list of batches loaded from the CSV
    pub batches: Vec<Batch>,
}

impl DatasetLoader {
    /// Parses a CSV file and loads the data into `Batch` structures.
    pub fn new(path: &str, device: &Device) -> CandleResult<Self> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);

        let mut batches = Vec::new();
        let mut current_epoch = None;
        
        let mut features = Vec::new();
        let mut residuals = Vec::new();
        let mut mask = Vec::new();

        for line in reader.lines() {
            let line = line?;
            let parts: Vec<&str> = line.split(',').collect();
            if parts.len() < 8 { continue; }

            let epoch: u32 = parts[0].parse().unwrap_or(0);
            
            if Some(epoch) != current_epoch {
                if current_epoch.is_some() {
                    Self::commit_batch(&mut batches, &mut features, &mut residuals, &mut mask, device)?;
                }
                current_epoch = Some(epoch);
            }

            Self::parse_line_into_buffers(&parts, &mut features, &mut residuals, &mut mask);
        }

        if !features.is_empty() {
            Self::commit_batch(&mut batches, &mut features, &mut residuals, &mut mask, device)?;
        }

        Ok(Self { batches })
    }

    /// Converts accumulated buffers into a padded `Batch` Tensor.
    fn commit_batch(
        batches: &mut Vec<Batch>,
        f: &mut Vec<f32>, 
        r: &mut Vec<f32>, 
        m: &mut Vec<f32>,
        device: &Device
    ) -> CandleResult<()> {
        if f.is_empty() { return Ok(()); }
        
        // Pad or truncate to MAX_SATS
        f.resize(MAX_SATS * NUM_FEATURES, 0.0);
        r.resize(MAX_SATS, 0.0);
        m.resize(MAX_SATS, 0.0);

        let f_tensor = Tensor::from_vec(f.clone(), (1, MAX_SATS, NUM_FEATURES), device)?;
        let r_tensor = Tensor::from_vec(r.clone(), (1, MAX_SATS), device)?;
        let m_tensor = Tensor::from_vec(m.clone(), (1, MAX_SATS), device)?;

        batches.push(Batch { features: f_tensor, residuals: r_tensor, mask: m_tensor });

        f.clear();
        r.clear();
        m.clear();
        Ok(())
    }

    /// Parses a single CSV line and appends it to the temporary buffers.
    fn parse_line_into_buffers(
        parts: &[&str],
        features: &mut Vec<f32>,
        residuals: &mut Vec<f32>,
        mask: &mut Vec<f32>,
    ) {
        if mask.len() < MAX_SATS {
            let snr: f32 = parts[2].parse().unwrap_or(0.0);
            let el: f32 = parts[3].parse().unwrap_or(0.0);
            let az: f32 = parts[4].parse().unwrap_or(0.0);
            let dop: f32 = parts[5].parse().unwrap_or(0.0);
            let lock: f32 = parts[6].parse().unwrap_or(0.0);
            let r_sq: f32 = parts[7].parse().unwrap_or(0.0);

            // Normalize features to [0, 1] or [-1, 1] range to stabilize gradients
            let normalized = crate::engine::ml::dataset::normalize_features(snr, el, az, dop, lock);

            features.extend_from_slice(&normalized);
            residuals.push(r_sq);
            mask.push(1.0);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;

    #[test]
    fn test_dataset_loader_parsing_and_padding() {
        let mut tmp_file = tempfile::NamedTempFile::new().unwrap();
        writeln!(tmp_file, "1,G15,27.00,33.82,108.04,-3485.6110,0,1208.9").unwrap();
        writeln!(tmp_file, "1,G20,32.00,56.01,228.93,-2412.4670,0,6.99").unwrap();
        writeln!(tmp_file, "2,G32,38.00,25.34,306.52,1802.7850,0,0.24").unwrap();

        let device = Device::Cpu;
        let loader = DatasetLoader::new(tmp_file.path().to_str().unwrap(), &device).unwrap();

        assert_eq!(loader.batches.len(), 2);
        
        let batch_1 = &loader.batches[0];
        assert_eq!(batch_1.features.dims(), &[1, 32, 5]);
        assert_eq!(batch_1.residuals.dims(), &[1, 32]);
        assert_eq!(batch_1.mask.dims(), &[1, 32]);

        let mask_1 = batch_1.mask.to_vec2::<f32>().unwrap();
        assert_eq!(mask_1[0][0], 1.0);
        assert_eq!(mask_1[0][1], 1.0);
        assert_eq!(mask_1[0][2], 0.0); // Padded
    }
}
